from pathlib import Path


def replace_once(path: Path, old: str, new: str) -> None:
    text = path.read_text(encoding="utf-8")
    if new in text:
        return
    if text.count(old) != 1:
        raise SystemExit(f"{path}: expected one patch anchor, found {text.count(old)}")
    path.write_text(text.replace(old, new, 1), encoding="utf-8")

runtime = Path("launcher/electron/runtime.cjs")
replace_once(
    runtime,
    '''  async bridgeStatus(operationName = "bridge-status") {\n    this.assertProductionProfile("Codex bridge status");\n    const result = await this.run(operationName, ["route", "status"], {\n      embedded: true,\n      message: "Checking Codex bridge route",\n      successMessage: "Codex bridge route checked",\n      timeoutMs: 15_000,\n    });\n    return parseBridgeRouteResult(result.stdout, { requireInstalled: true });\n  }\n''',
    '''  async bridgeStatusDiagnostic(operationName = "bridge-status-diagnostic") {\n    this.assertProductionProfile("Codex bridge diagnostics");\n    const result = await this.run(operationName, ["route", "status"], {\n      embedded: true,\n      message: "Inspecting Codex bridge route",\n      successMessage: "Codex bridge route inspected",\n      timeoutMs: 15_000,\n      acceptedExitCodes: [0, 1],\n    });\n    let parsed;\n    try {\n      parsed = JSON.parse(result.stdout);\n    } catch {\n      return {\n        commandExitCode: result.code,\n        parseError: "Codex bridge route command returned invalid JSON",\n        stdoutChars: result.stdout.length,\n        stderr: result.stderr.trim(),\n      };\n    }\n    return { commandExitCode: result.code, ...parsed };\n  }\n\n  async bridgeStatus(operationName = "bridge-status") {\n    this.assertProductionProfile("Codex bridge status");\n    const result = await this.run(operationName, ["route", "status"], {\n      embedded: true,\n      message: "Checking Codex bridge route",\n      successMessage: "Codex bridge route checked",\n      timeoutMs: 15_000,\n    });\n    return parseBridgeRouteResult(result.stdout, { requireInstalled: true });\n  }\n''',
)
replace_once(
    runtime,
    '''    const result = await this.runSetup("core-setup", args, {\n      message: "Installing ChatGPT Web models into Codex",\n      successMessage: "Codex integration installed",\n      timeoutMs: CORE_SETUP_TIMEOUT_MS,\n    });\n    return { ...result, mode };\n''',
    '''    const result = await this.runSetup("core-setup", args, {\n      message: "Installing ChatGPT Web models into Codex",\n      successMessage: "Codex integration installed",\n      timeoutMs: CORE_SETUP_TIMEOUT_MS,\n      afterRuntimeReady: async () => {\n        const route = await this.bridgeStatus("core-setup");\n        if (!route.installed || !route.active) {\n          throw new Error("Codex integration setup completed but the bridge route is not active");\n        }\n        if (this.platform === "win32" && route.staticCatalogActive !== true) {\n          throw new Error(\n            "Codex integration setup completed but the managed Windows model catalog is not active",\n          );\n        }\n      },\n    });\n    return { ...result, mode, catalogVerified: this.platform === "win32" };\n''',
)

main = Path("launcher/electron/main.cjs")
replace_once(
    main,
    '''  createLogger,\n  exportSanitizedLogs,\n  installProcessDiagnosticGuards,\n  registerLoggedIpc,\n} = require("./logging.cjs");\n''',
    '''  createLogger,\n  exportSanitizedLogs,\n  installProcessDiagnosticGuards,\n  registerLoggedIpc,\n  sanitizeForExport,\n} = require("./logging.cjs");\n''',
)
replace_once(
    main,
    '''let updateController = null;\n\nfunction findFreePort() {\n''',
    '''let updateController = null;\n\nfunction coreSetupStateSnapshot(state) {\n  return {\n    coreSetupComplete: state.coreSetupComplete === true,\n    codexCatalogVerified: state.codexCatalogVerified === true,\n    codexRestartRequired: state.codexRestartRequired === true,\n    browserInteractionMode: state.browserInteractionMode,\n    mcpRuntimeInstalled: state.mcpRuntimeInstalled === true,\n    mcpSetupComplete: state.mcpSetupComplete === true,\n  };\n}\n\nasync function collectCoreSetupDiagnostic({ stage, stateStore, error = null }) {\n  let route;\n  try {\n    route = await runtimeHost.bridgeStatusDiagnostic(`core-setup-diagnostic-${stage}`);\n  } catch (caught) {\n    route = { diagnosticError: caught instanceof Error ? caught.message : String(caught) };\n  }\n  let runtime;\n  try {\n    const current = runtimeHost.runtimeConfigSnapshot();\n    runtime = {\n      configured: current.configured === true,\n      owner: current.owner,\n      mode: current.mode,\n      releaseVersion: current.config?.releaseVersion ?? null,\n      browserInteractionMode: current.config?.browserInteractionMode ?? null,\n      subagentProtocol: current.config?.subagentProtocol ?? null,\n    };\n  } catch (caught) {\n    runtime = { diagnosticError: caught instanceof Error ? caught.message : String(caught) };\n  }\n  let browser;\n  try {\n    const current = browserHost.snapshot();\n    browser = {\n      authenticated: current.authenticated === true,\n      status: current.status,\n      url: current.url,\n    };\n  } catch (caught) {\n    browser = { diagnosticError: caught instanceof Error ? caught.message : String(caught) };\n  }\n  return {\n    schemaVersion: 1,\n    at: new Date().toISOString(),\n    stage,\n    launcherVersion: app.getVersion(),\n    platform: process.platform,\n    codexHome: process.env.CODEX_HOME || null,\n    state: coreSetupStateSnapshot(stateStore.read()),\n    route,\n    runtime,\n    browser,\n    ...(error ? { error: error instanceof Error ? error.message : String(error) } : {}),\n  };\n}\n\nfunction writeCoreSetupDiagnostic(payload, logger) {\n  try {\n    const destinationPath = path.join(app.getPath("desktop"), "codex-web-gpt-setup-diagnostic-latest.json");\n    fs.writeFileSync(destinationPath, `${JSON.stringify(sanitizeForExport(payload), null, 2)}\\n`, { mode: 0o600 });\n    logger.info("codex.setup_diagnostic_saved", { stage: payload.stage, destinationPath });\n    return destinationPath;\n  } catch (error) {\n    logger.warn("codex.setup_diagnostic_save_failed", {\n      stage: payload.stage,\n      message: error instanceof Error ? error.message : String(error),\n    });\n    return null;\n  }\n}\n\nfunction findFreePort() {\n''',
)
old_setup = '''  handle("launcher:setup-core", async () => {\n    const setupState = stateStore.read();\n    if (setupState.browserInteractionMode === "automatic") {\n      const browser = await browserHost.probeAuthentication();\n      if (!browser.authenticated) {\n        throw new Error(\n          IS_DEV_PROFILE\n            ? "Sign in to the isolated DEV ChatGPT profile before configuring the harness"\n            : "Sign in to ChatGPT before installing the Codex integration",\n        );\n      }\n    }\n    if (setupState.browserInteractionMode === "automatic"\n      && !setupState.coreSetupComplete\n      && !(smokePassedThisSession || smokePassedForCurrentVersion(setupState))) {\n      throw new Error(\n        IS_DEV_PROFILE\n          ? "Run the browser smoke test before configuring the DEV harness"\n          : "Run the browser smoke test before installing the Codex integration",\n      );\n    }\n    const result = IS_DEV_PROFILE ? await runtimeHost.setupDevCore() : await runtimeHost.setupCore();\n    stateStore.update({\n      coreSetupComplete: true,\n      codexCatalogVerified: IS_DEV_PROFILE ? true : false,\n      codexRestartRequired: IS_DEV_PROFILE ? false : true,\n      zeroRiskProEnabled: runtimeHost.runtimeConfigSnapshot().config?.zeroRiskProEnabled === true,\n      ...(result.mode === "full" ? {\n        mcpRuntimeInstalled: true,\n        mcpSetupComplete: false,\n        mcpGuideStep: 2,\n      } : {\n        mcpSetupComplete: false,\n        mcpRuntimeInstalled: false,\n        mcpGuideStep: 0,\n      }),\n    });\n    await browserHost.returnToIdle().catch((error) => {\n      logger.warn("browser.idle_cleanup_failed", {\n        message: error instanceof Error ? error.message : String(error),\n      });\n    });\n    if (!IS_DEV_PROFILE) startCatalogVerificationMonitor({ logger, stateStore });\n    return { ok: true, stdout: result.stdout, restartRequired: !IS_DEV_PROFILE };\n  });\n'''
new_setup = '''  handle("launcher:setup-core", async () => {\n    const attemptId = `${Date.now()}-${Math.random().toString(16).slice(2, 10)}`;\n    const setupState = stateStore.read();\n    logger.info("codex.setup_attempt_started", {\n      attemptId,\n      state: coreSetupStateSnapshot(setupState),\n    });\n    if (!IS_DEV_PROFILE) {\n      const before = await collectCoreSetupDiagnostic({ stage: "before", stateStore });\n      writeCoreSetupDiagnostic({ ...before, attemptId }, logger);\n      logger.info("codex.setup_state_before", { attemptId, diagnostic: before });\n    }\n    try {\n      if (setupState.browserInteractionMode === "automatic") {\n        const browser = await browserHost.probeAuthentication();\n        if (!browser.authenticated) {\n          throw new Error(\n            IS_DEV_PROFILE\n              ? "Sign in to the isolated DEV ChatGPT profile before configuring the harness"\n              : "Sign in to ChatGPT before installing the Codex integration",\n          );\n        }\n      }\n      if (setupState.browserInteractionMode === "automatic"\n        && !setupState.coreSetupComplete\n        && !(smokePassedThisSession || smokePassedForCurrentVersion(setupState))) {\n        throw new Error(\n          IS_DEV_PROFILE\n            ? "Run the browser smoke test before configuring the DEV harness"\n            : "Run the browser smoke test before installing the Codex integration",\n        );\n      }\n      const result = IS_DEV_PROFILE ? await runtimeHost.setupDevCore() : await runtimeHost.setupCore();\n      const catalogVerified = IS_DEV_PROFILE || result.catalogVerified === true;\n      const state = stateStore.update({\n        coreSetupComplete: true,\n        codexCatalogVerified: catalogVerified,\n        codexRestartRequired: IS_DEV_PROFILE ? false : true,\n        zeroRiskProEnabled: runtimeHost.runtimeConfigSnapshot().config?.zeroRiskProEnabled === true,\n        ...(result.mode === "full" ? {\n          mcpRuntimeInstalled: true,\n          mcpSetupComplete: false,\n          mcpGuideStep: 2,\n        } : {\n          mcpSetupComplete: false,\n          mcpRuntimeInstalled: false,\n          mcpGuideStep: 0,\n        }),\n      });\n      send("launcher:state-changed", state);\n      await browserHost.returnToIdle().catch((error) => {\n        logger.warn("browser.idle_cleanup_failed", {\n          message: error instanceof Error ? error.message : String(error),\n        });\n      });\n      if (!IS_DEV_PROFILE && !catalogVerified) startCatalogVerificationMonitor({ logger, stateStore });\n      else stopCatalogVerificationMonitor();\n      if (!IS_DEV_PROFILE) {\n        const after = await collectCoreSetupDiagnostic({ stage: "success", stateStore });\n        writeCoreSetupDiagnostic({ ...after, attemptId }, logger);\n        logger.info("codex.setup_attempt_completed", { attemptId, diagnostic: after });\n      }\n      return { ok: true, stdout: result.stdout, restartRequired: !IS_DEV_PROFILE };\n    } catch (error) {\n      if (!IS_DEV_PROFILE) {\n        const failed = await collectCoreSetupDiagnostic({ stage: "failure", stateStore, error });\n        const diagnosticPath = writeCoreSetupDiagnostic({ ...failed, attemptId }, logger);\n        logger.error("codex.setup_attempt_failed", { attemptId, diagnostic: failed, diagnosticPath });\n        const primary = error instanceof Error ? error.message : String(error);\n        throw new Error(diagnosticPath\n          ? `${primary}; detailed diagnostic saved to ${diagnosticPath}`\n          : primary);\n      }\n      throw error;\n    }\n  });\n'''
replace_once(main, old_setup, new_setup)

# Add a focused regression without disturbing the large existing host fixtures.
test_path = Path("launcher/tests/runtime-host.test.cjs")
text = test_path.read_text(encoding="utf-8")
marker = '''test("launcher leaves an already connected route unchanged", async () => {\n'''
if 'Windows core setup fails closed when the managed model catalog is not active' not in text:
    addition = '''test("Windows core setup fails closed when the managed model catalog is not active", async () => {\n  const calls = [];\n  const host = Object.create(RuntimeHost.prototype);\n  host.platform = "win32";\n  host.launcherProfile = "production";\n  host.currentOperation = () => null;\n  host.runtimeConfigSnapshot = () => ({ configured: true, owner: "launcher", mode: "browser-only", config: {} });\n  host.browserInteractionMode = () => "automatic";\n  host.browserDescriptorPath = "C:\\\\temp\\\\launcher-browser.json";\n  host.runSetup = async (_name, _args, options) => {\n    calls.push("runSetup");\n    await options.afterRuntimeReady();\n    return { stdout: "ok" };\n  };\n  host.bridgeStatus = async () => ({ installed: true, active: true, staticCatalogActive: false, errors: [] });\n\n  await assert.rejects(\n    RuntimeHost.prototype.setupCore.call(host),\n    /managed Windows model catalog is not active/,\n  );\n  assert.deepEqual(calls, ["runSetup"]);\n});\n\n'''
    if marker not in text:
        raise SystemExit("runtime-host test insertion anchor missing")
    text = text.replace(marker, addition + marker, 1)
    test_path.write_text(text, encoding="utf-8")
